// Generated by scripts/build-lesson-bundles.cjs.
((globalThis, register) => {
'use strict';
globalThis.KENGURU_CHOICE_LAYOUTS = {};
'use strict';

globalThis.makeMedvezhonokEdition = function (year, grade, rows, material = {}) {
  const letters = 'АБВГД';
  const plain = value => value.replace(/<\/?(?:em|strong|u)>/g, '');
  const escape = value => value.replaceAll('&', '&amp;').replaceAll('<', '&lt;').replaceAll('>', '&gt;');
  const grades = grade.split('-').map(Number);
  const lessons = rows.map(({author, question, choices, key, review, figure, unrated, points}, index) => {
    const [title, idea, check] = review;
    const answer = letters.indexOf(key);
    const textChoices = choices.map(plain);
    const options = figure?.options?.map(({src, detailSrc, description, pixelWidth, pixelHeight}, i) => ({
      image: src, ...(detailSrc ? {detailSrc} : {}), description, pixelWidth, pixelHeight, text: figure.onlyPictures ? '' : textChoices[i],
    })) ?? textChoices.map(text => ({text}));
    return {
      number: index + 1, title, author, question: plain(question), choices: textChoices,
      ...(plain(question) !== question ? {formattedQuestion: question} : {}),
      ...(textChoices.some((value,i) => value !== choices[i]) ? {formattedChoices: choices} : {}),
      ...(unrated ? {questionNote: unrated, archiveAnswer: key} : {}),
      ...(figure ? {
        choiceLayout: {options, condition: figure.condition},
        choiceImages: options.map(option => option.image),
        ...(figure.condition ? {conditionImage: figure.condition.src, conditionAlt: figure.condition.alt} : {}),
      } : {}),
      answer: unrated ? null : answer, points: points ?? (index < 10 ? 3 : index < 20 ? 4 : 5),
      skill: 'Русский медвежонок · Языкознание', hideIntroText: true, showCompletedStep: true,
      steps: [
        ['Выбор', 'Условие задачи', ''],
        ['Первый шаг', 'Рассуждение', idea],
        ['Проверка', 'Проверка', check],
        ['Ответ', unrated ? 'Ответ в архивном ключе' : 'Ответ', ''],
      ],
    };
  });
  const scenes = rows.map(({review, key}, i) => {
    const terms = review.slice(1).map(step => [...new Set(
      Array.from(step.matchAll(/«([^«»\n]{1,44})»/gu), match => match[1])
    )].slice(0, 5));
    return (step, frame) => {
      if (!step) return '';
      const result = lessons[i].choices[letters.indexOf(key)].replace(/^\[(.*)\][.]?$/, '$1');
      const tokens = step === 3 ? [key + (result ? ' · ' + result : '')] : terms[step-1];
      if (step < 3 && tokens.length < 2) return '';
      return '<div class="word-scene" data-result="' + (step === 3) + '">' + tokens.map((token, index) => {
        const reveal = Math.min(1, Math.max(0, (frame - index * 0.65) / 0.42));
        return '<span class="word-token" style="--reveal:' + reveal.toFixed(3) + '">' + escape(token) + '</span>';
      }).join('') + '</div>';
    };
  });
  const reviewedKey = rows.some(row => row.reviewedEdition);
  return {
    id: year + '-medvezhonok-' + grade, year, grades, subject: 'ru',
    label: grades.join('–') + (grades.length === 1 ? ' класс' : ' классы'),
    sources: {
      contest: 'Русский медвежонок',
      tasksUrl: 'assets/medvezhonok/' + year + '/' + (material.tasksFile ?? grade + '.pdf'),
      reviewedKey,
      answersUrl: 'assets/medvezhonok/' + year + '/' + (reviewedKey ? 'reviewed-' + grade + '.pdf' : material.answersFile ?? grade + '-answers.pdf'),
      ...(material.solutionsFile ? {solutionUrl: 'assets/medvezhonok/' + year + '/' + material.solutionsFile} : {}),
      ...(year === 2004 && grade === '2-3' ? {solutionUrl: 'assets/medvezhonok/2004/2-3-answers.pdf'} : {}),
    },
    lessons, scenes,
  };
};

register(globalThis.makeMedvezhonokEdition(2023, "6-7", [{"author":"А. Ковалёва","question":"Летом мы идём по улице, а над нами вьётся целый рой _____.","choices":["кошмары́","комшары́","мошкары́","мокшары́","шокмары́"],"key":"В","review":["Кто вьётся роем","«Рой» бывает у множества мелких крылатых насекомых. Летом над людьми могут виться мелкие мошки.","Собрание мошек называют «мошкара». После слова «рой» нужна форма «мошкары́»."]},{"author":"А. Ковалёва","question":"Какой Иван не является персонажем русских народных сказок?","choices":["Иван-царевич","Иван-дурак","Иван-чай","Иванушка","Иван — крестьянский сын"],"key":"В","review":["Иваны в сказках","Иван-царевич, Иван-дурак, Иванушка и Иван — крестьянский сын встречаются в сказках как герои.","«Иван-чай» — название растения и напитка из него. Это единственный вариант без сказочного персонажа."]},{"author":"А. Сомин","question":"Какое из этих сочетаний обычно описывает не причину?","choices":["из-за дождя","из-за болезни","из-за денег","из-за границы","из-за пустяка"],"key":"Г","review":["Два значения «из-за»","Дождь, болезнь, деньги и пустяк могут стать причиной какого-нибудь события. С ними «из-за» значит «по причине».","«Приехать из-за границы» означает приехать из другой страны. Здесь сочетание обозначает направление и исходное место."]},{"author":"О. Подлесская","question":"Какое слово не связано с приготовлением и приёмом пищи?","choices":["стряпать","почивать","кулинар","трапезная","столовая"],"key":"Б","review":["Слова о еде","Стряпать — готовить пищу, кулинар её готовит, а трапезная и столовая предназначены для приёма пищи.","«Почивать» означает «спать» или «отдыхать». У слова другая тема."]},{"author":"А. Сомин","question":"Какое из этих существительных образует словосочетания с числительными?","choices":["свинина","рыбина","говядина","баранина","курятина"],"key":"Б","review":["Что можно сосчитать","Свинина, говядина, баранина и курятина обычно называют мясо как вещество. Чтобы его сосчитать, нужны единицы вроде «два куска».","«Рыбина» — отдельная рыба. Можно сразу сказать «одна рыбина», «две рыбины»."]},{"author":"А. Остроумова","question":"В каком предложении <em>знать не знаю</em> имеет не то значение, что в остальных?","choices":["Какую свитку? у меня нет никакой свитки! я знать не знаю твоей свитки! (Н. В. Гоголь)","О чём вы? Какие такие дневники, знать не знаю! (В. В. Лебедев)","Какие промежду нас могут быть дела? Я вас знать не знаю! (И. Ф. Горбунов)","Знать не знаю, но видел, как у неё из сумочки выпал загранпаспорт. (С. В. Бурлаченко)","Помилуй, говорит, не губи, знать не знаю, ведать не ведаю я про твои деньги, про что говоришь ты, в первый раз слышу. (Б. Л. Пастернак)"],"key":"Г","review":["Что отвергает говорящий","В большинстве примеров «знать не знаю» усиливает отрицание: говорящий категорически отвергает знакомство, сведения о предмете или событии.","В примере Г говорящий сообщает конкретную увиденную деталь — выпавший загранпаспорт. Оборот ограничивает то, что ему известно, перед противопоставлением «но видел»."]},{"author":"Л. Фёдорова","question":"Как обычно не называют человека?","choices":["блондин","брюнет","шатен","рыжий","гнедой"],"key":"Д","review":["Слова о цвете волос","О человеке с определённым цветом волос говорят «блондин», «брюнет», «шатен» или «рыжий».","«Гнедой» обычно обозначает масть лошади: коричневую шерсть с чёрными гривой и хвостом. Человека так обычно не называют."]},{"author":"Д. Швайгер","question":"Мама рассердилась на сына и сказала, что он довёл её до _____ каления. Вставьте пропущенное слово.","choices":["красного","синего","жёлтого","белого","чёрного"],"key":"Г","review":["Рассерженная мама","При сильном нагреве металл начинает светиться. В устойчивом выражении о гневе этот образ передаёт очень высокую степень накала.","Говорят «довести до белого каления». Пропущено слово «белого»."]},{"author":"Л. Фёдорова","question":"Какая буква раньше не считалась согласной?","choices":["з","й","л","м","х"],"key":"Б","review":["Буква из «и»","«Й» выглядит как «и» с маленьким знаком сверху. Её долго называли «и краткое» и рассматривали как разновидность буквы И.","Сегодня «й» обозначает согласный звук [й]. Из списка именно эта буква раньше не относилась к обычным согласным буквам."]},{"author":"О. Подлесская","question":"В каком из глаголов нельзя поменять приставку от- на о- и получить новый глагол?","choices":["отступиться","отправиться","отказаться","отпираться","отсмеяться"],"key":"Д","review":["Замена приставки","Получаются пары «отступиться — оступиться», «отправиться — оправиться», «отказаться — оказаться», «отпираться — опираться».","Замена в «отсмеяться» дала бы «осмеяться». Есть глагол «осмеять», но обычной формы «осмеяться» с таким строением нет."]},{"author":"И. Рубанов","question":"Как не говорят?","choices":["вышел из себя","не в себе","нашёл себя","пришёл в себя","ушёл из себя"],"key":"Д","review":["Выражения со словом «себя»","Есть выражения «выйти из себя» о гневе, «не в себе» о состоянии и «прийти в себя» о возвращении к нормальному состоянию.","«Найти себя» значит найти своё место или дело. Вместо «ушёл из себя» в устойчивом обороте говорят «вышел из себя»."]},{"author":"И. Рубанов","question":"Какое из этих слов значительно чаще других называет цвет?","choices":["кефирный","масляный","молочный","сырный","творожный"],"key":"В","review":["Названия цветов","О прилагательном спрашивают как о названии оттенка. Можно сказать «молочный цвет» о мягком белом цвете молока.","«Кефирный», «масляный», «сырный» и «творожный» обычно указывают на состав или сходство с продуктом. Цвет чаще называется «молочным»."]},{"author":"О. Подлесская","question":"Перед вами три испанских слова, обозначающие птиц: buho ‘сова’, gallina ‘курица’, golondrina ‘ласточка’. Эти слова употребляются в переносном значении: ‘трус’, ‘туристическая моторная лодка’, ‘ночной автобус в Мадриде’. Расставьте испанские слова, чтобы они соответствовали переносным значениям:","choices":["buho, gallina, golondrina","buho, golondrina, gallina","gallina, buho, golondrina","gallina, golondrina, buho","golondrina, gallina, buho"],"key":"Г","review":["Испанские названия птиц","Сова активна ночью, поэтому <em>buho</em> подходит ночному автобусу. Курица воспринимается как пугливая, что соответствует слову <em>gallina</em> в значении «трус».","Остаётся моторная лодка. Её название связано с быстрой ласточкой, <em>golondrina</em>. Получаем <em>gallina, golondrina, buho</em>."]},{"author":"Л. Фёдорова","question":"Какой из примеров сильно отличается по смыслу от других?","choices":["наизнанку","задом наперёд","вдоль и поперёк","вверх тормашками","шиворот-навыворот"],"key":"В","review":["Как что-то повернуто","«Наизнанку», «задом наперёд», «вверх тормашками» и «шиворот-навыворот» описывают перемену привычного положения.","«Вдоль и поперёк» означает во всех направлениях или «очень подробно». Оно не про изменение положения предмета."]},{"author":"О. Подлесская","question":"В каком порядке должны идти перепутанные предложения из истории Михаила Зощенко?\n1. Вдруг слышу, кто-то на лестнице позвонил.\n2. И вот я однажды приехал в город на свою городскую квартиру.\n3. И можете себе представить — передо мной на площадке сидит моя собака.\n4. И сижу там, горюю, что у меня пропала такая дивная собака.\n5. Я открываю дверь.","choices":["1, 5, 4, 3, 2","1, 5, 3, 2, 4","2, 3, 1, 5, 4","2, 4, 1, 5, 3","2, 5, 4, 3, 1"],"key":"Г","review":["Порядок событий","Сначала рассказчик приезжает в город, затем огорчается из-за пропажи собаки. Это предложения 2 и 4.","Потом слышен звонок 1, рассказчик открывает дверь 5 и видит собаку 3. Связный порядок — 2, 4, 1, 5, 3."]},{"author":"Л. Фёдорова","question":"Найдите два слова, одно из которых является производным от другого: 1) двойник, 2) двойка, 3) двойня, 4) двоечник, 5) двушка.","choices":["1 и 2","1 и 3","2 и 4","3 и 4","2 и 5"],"key":"В","review":["Откуда взялся «двоечник»","Сравним значения. «Двоечником» называют того, кто часто получает плохую оценку.","Такая оценка называется «двойка». «Двоечник» образован от «двойка», так что подходят 2 и 4."]},{"author":"Е. Бикмаев","question":"В летописях годичные (погодные) записи обычно начинаются словами «В лето…». А что это означает?","choices":["‘давным-давно’","‘в год’","‘летом’","‘в тёплое время’","‘в южных районах Руси’"],"key":"Б","review":["Летописное «в лето»","В летописи описывают события определённого года. Каждую запись открывают словами с указанием, когда всё произошло.","Поэтому «в лето» означает «в год». Тогда слово «лето» могло называть целый год."]},{"author":"М. Рубинштейн","question":"«Подружейные собаки» — это собаки, которые __________.","choices":["ходят с хозяевами на охоту","хорошо играют с детьми","не кусаются","ладят с кошками","помогают слепым людям ориентироваться"],"key":"А","review":["Подружейные собаки","В «подружейные» скрыто слово «ружьё»: охотничьих собак используют при охоте с ружьём.","Они помогают найти, поднять или принести добычу. Таких собак берут с собой на охоту."]},{"author":"П. Долгополов","question":"Какой глагол чаще других используется в текстах, описывающих природу в утреннее время?","choices":["учиться","преподавать","работать","исследовать","заниматься"],"key":"Д","review":["О начале утра","Утром над горизонтом появляется свет, начинается рассвет. Для этого есть выражения «занимается заря», «занимается день».","Здесь «заниматься» значит начинаться, светать. Остальные глаголы обычно называют действия человека."]},{"author":"О. Подлесская","question":"В каком примере дружно означает не то, что в других?","choices":["Взялись <strong>дружно</strong>, хотя и беспорядочно, то и дело толкаясь и мешая друг другу. (В. Быков)","Тут все девушки снова <strong>дружно</strong> расхохотались, а сама Маяна от хохота даже не удержалась на ногах и свалилась на дрова, сложенные на кухонной веранде. (Ф. Искандер)","Если ему во время обычной утренней прогулки приходилось встречаться со знакомыми, то прохожие за несколько кварталов слышали, как кричит комендант и как <strong>дружно</strong> вслед за ним лают его мопсы. (А. Куприн)","Цс-сык! ― явственно звучало вокруг, как будто десятки кос <strong>дружно</strong> резали густую, сочную траву. (В. Вересаев)","И теперь можем сказать: не было ни одного дома, где бы жили и работали так <strong>дружно</strong>, как жили наши любимцы. (М. Пришвин)"],"key":"Д","review":["Значения слова «дружно»","В четырёх примерах люди, собаки или косы действуют вместе или одновременно: взялись за дело, засмеялись, залаяли, начали косить.","В последнем примере «жили и работали дружно» означает «жили в согласии». Здесь важны отношения, а не одновременность."]},{"author":"Л. Фёдорова","question":"Но эта важная забава\nДостойна старых обезьян\nХвалёных дедовских времян…\n У А. С. Пушкина в этих строчках встречается неожиданная форма родительного падежа слова время. А сколько слов из ряда: имя, знамя, время, племя, семя, стремя — имеют такую форму в современном языке?","choices":["ни одно","одно","два","три","все"],"key":"В","review":["Родительный у слов на «мя»","Поэт употребил «времян» там, где сейчас говорят «времён». Сравним родительный множественного числа у остальных слов.","Получаются «имён», «знамён», «времён», «племён», «семян» и «стремян». Сочетание -мян сохранилось в двух последних."]},{"author":"А. Пиперски","question":"Даны слова: завал, запал, задел, завыл. Сколько здесь существительных, а сколько глаголов?","choices":["2 и 3","3 и 2","3 и 3","3 и 4","4 и 3"],"key":"В","review":["Существительное или глагол","«Завал», «запал» и «задел» могут называть предмет или положение дел: завал на дороге, запал для разжигания, задел на будущее.","Есть и «запал» от «запасть», «задел» от «задеть», «завыл» от «завыть». Получается по три существительных и глагола."]},{"author":"Л. Фёдорова","question":"Маша играет на пианино. Миша смотрит в окно. Игроки вышли на поле. В море плещут волны. Ничего не видно, но слышно шум прибоя. Сколько здесь слов в винительном падеже?","choices":["два","три","четыре","пять","не меньше шести"],"key":"Б","review":["Слова в винительном падеже","«Смотрит во что?» — «в окно». «Вышли на что?» — «на поле». Это винительный падеж. В «на пианино» падеж предложный, как и в «в море».","«Слышно что?» — «шум». Это третий винительный. «Ничего» и «прибоя» — формы родительного падежа."]},{"author":"И. Рубанов","question":"Есть что _____. Как нельзя закончить эту фразу?","choices":["есть","играть","смотреть","танцевать","всеми глаголами (А)–(Г) можно закончить фразу"],"key":"Д","review":["Глагол после «есть что»","В «есть что» слово «что» указывает на предмет действия. Можно иметь что поесть или что посмотреть.","Можно также иметь что играть — например, пьесу — и что танцевать, например танго. Все четыре окончания возможны."]},{"author":"О. Подлесская","question":"Перед вами — начало стихотворения Дмитрия Авалиани. Продолжите его. Я ящерка ютящейся эпохи, щемящий шелест чувственных _____.","choices":["шагов","листов","дриад","цикад","сверчков"],"key":"Г","review":["Алфавит задом наперёд","После начального «Я» первые буквы слов у Авалиани идут по алфавиту в обратную сторону: Я, Ю, Э, Щ, Ш, Ч. Буквы, с которых здесь слово не начинается, пропускаются.","За Ч в обратном порядке идёт Ц. Из вариантов подходит «цикад», и шелест их крыльев согласуется с образом стихотворения."]},{"author":"О. Подлесская","question":"Благодаря их опыту я лучше понимаю, какого это — потерять дом. Какое слово в этом примере нужно исправить?","choices":["благодаря","опыту","лучше","какого","это"],"key":"Г","review":["Каково это","В выражении нужно назвать ощущение от потери дома. Для этого употребляют «понимаю, каково это».","Форма «какого» отвечает на вопрос «какого дома?» и относится к существительному. Здесь нужно слово «каково»."]},{"author":"Е. Бикмаев","question":"У какого из этих слов нельзя однозначно определить род?","choices":["единицы","десятки","сотни","тысячи","миллионы"],"key":"Б","review":["Род существительных","Поставим слова в единственное число. «Единица», «сотня» и «тысяча» женского рода, «миллион» — мужского.","«Десятки» может быть множественным числом и от «десяток» мужского рода, и от «десятка» женского. Одного рода установить нельзя."]},{"author":"Л. Фёдорова","question":"Все слова в ответах, кроме одного, сочетаются с одним и тем же существительным. Какое лишнее?","choices":["капуста","картошка","крючок","пятачок","пуговка"],"key":"А","review":["Слова о форме носа","Нос может быть картошкой, крючком, пятачком или пуговкой. Сравнения передают разные его формы.","«Капуста» в этом ряду не употребляется как обычное обозначение формы носа."]},{"author":"А. Сомин","question":"В Казани работает школа-интернат «СОлНЦе» — специализированный олимпиадно-научный центр. Одно из мероприятий, которое там проводят, — это __________.","choices":["Путешествие в Мир Исследований","Конкурс Изобретательских Технологий","Зимняя Научная Олимпиада","Лаборатория Увлекательных Наук","Мастерская Юных Учёных"],"key":"Г","review":["Название по буквам","«СОлНЦе» скрывает сокращение из названия школы. Попробуем найти похожий приём в названии мероприятия.","Первые буквы слов «Лаборатория Увлекательных Наук» дают ЛУН. В названии добавляют А, чтобы получилось «ЛУНа» и пара к «СОлНЦу»."]},{"author":"И. Иткин","question":"Даны существительные тохарского B языка (одного из древних индоевропейских языков) и образованные от них прилагательные:\nśampā ‘высокомерие, гордыня’ — śampāsse ‘высокомерный’\nersnā ‘внешность, форма’ — ersnāssu ‘хорошо сложенный, красивый’\nentse ‘жадность, зависть’ — entsesse ‘жадный, завистливый’\nyärpo ‘заслуга, благое дело’ — yärpossu ‘достойный награды’\nśaul ‘жизнь’ — śaulässu ‘жизненный’\nwaike ‘ложь’ — waikesse ‘лживый’\nwer ‘ненависть’ — _____ ‘исполненный ненависти’\nakālk ‘желание’ — _____ ‘полный желания’\nspeltke ‘старание’ — _____ ‘старательный’\nКак правильно заполнить пропуски?","choices":["werässe, akālkässe, speltkesse","werässe, akālkässu, speltkesse","werässe, akālkässu, speltkessu","werässu, akālkässe, speltkesse","werässu, akālkässe, speltkessu"],"key":"В","review":["Тохарские прилагательные","После гласной добавляется -sse или -ssu сразу, после согласной возникает -ä-. В примерах -sse связано с дурными свойствами, а -ssu с положительными или нейтральными.","Ненависть даёт werässe, желание — akālkässu. Старание положительно, а speltke кончается гласной, поэтому получается speltkessu."]}], {"year":2023,"grade":"6-7","tasksFile":"6-7.pdf","answersFile":"6-7-answers.pdf","sourceUrl":"https://konkurs43.ru/rm/task2023-1.zip"}), globalThis.KENGURU_CHOICE_LAYOUTS, {});
})({KenguruVisual: globalThis.KenguruVisual}, globalThis.KenguruEditions.register);
